TOOL_ACTIVATE = "activate"
TOOL_COMPLETE = "complete"
TOOL_CANCEL = "cancel"
TOOL_SET_FIELDS = "set_fields"
"""Batch tool for collect field values."""

TOOL_CORRECT = "correct"

TOOL_RESOLVE_TOOL_CONFIRMATION = "resolve_tool_confirmation"
"""Interpret the user's reply to a pending ``requires_confirmation`` gate."""

TOOL_SEARCH_KNOWLEDGE = "search_knowledge"
"""On-demand knowledge retrieval."""

TOOL_CANNOT_HELP = "cannot_help"
"""Decline an unsupported request."""

TOOL_LISTEN = "listen"
"""End the turn silently and wait for the next user utterance."""

TOOL_HANGUP = "hangup"
"""End the conversation after a goodbye (deferred hangup on voice-stream)."""

# Engine-owned tool names. Builder ``@tool`` functions must not reuse these.
FRAMEWORK_TOOL_NAMES: frozenset[str] = frozenset(
    {
        TOOL_ACTIVATE,
        TOOL_COMPLETE,
        TOOL_CANCEL,
        TOOL_SET_FIELDS,
        TOOL_CORRECT,
        TOOL_RESOLVE_TOOL_CONFIRMATION,
        TOOL_SEARCH_KNOWLEDGE,
        TOOL_CANNOT_HELP,
        TOOL_LISTEN,
        TOOL_HANGUP,
    }
)

# ---------------------------------------------------------------------------
# JSON type mapping for Python annotations
# ---------------------------------------------------------------------------

_PY_TYPE_TO_JSON: Dict[Any, str] = {
    int: "integer",
    float: "number",
    bool: "boolean",
    str: "string",
}

# Map MemoryField type strings to JSON schema types.
# Unmapped types (text, categorical, json, any) default to "string".
_MEMORY_TYPE_TO_JSON: Dict[str, str] = {
    MEMORY_FIELD_TYPE_BOOL: "boolean",
    MEMORY_FIELD_TYPE_INT: "integer",
    MEMORY_FIELD_TYPE_FLOAT: "number",
    MEMORY_FIELD_TYPE_LIST: "array",
}


def _json_type_for_memory_entry(entry: Optional[MemoryField]) -> str:
    """Return the JSON schema type for a memory entry.

    Maps the entry's ``type`` field to an OpenAI JSON schema type string.
    Defaults to ``"string"`` when *entry* is ``None`` or its type is unmapped.
    """
    if entry is None:
        return "string"
    return _MEMORY_TYPE_TO_JSON.get(entry.type, "string")


_TOOL_FUNCTION = "function"


def _no_arg_tool_parameters() -> Dict[str, Any]:
    """JSON-schema object with no properties (complete/cancel take no args)."""
    return {
        "type": "object",
        "properties": {},
        "required": [],
        "additionalProperties": False,
    }


# Canonical schemas, not OpenAI dicts: ``from_litellm_json_format`` mutates
# nested ``parameters``, so module-level dicts would leak across turns.
_COMPLETE_SCHEMA = AgentToolSchema(
    name=TOOL_COMPLETE,
    description=(
        "Signal that the current skill has gathered all required information "
        "and should be marked as complete."
    ),
    parameters=_no_arg_tool_parameters(),
    strict=False,
)
_CANCEL_SCHEMA = AgentToolSchema(
    name=TOOL_CANCEL,
    description=(
        "Abandon the active skill only when the user clearly cancels the whole "
        "task. Dropping a follow-up question or asking to return to the task "
        "does not cancel it. If the scope is unclear, ask before cancelling."
    ),
    parameters=_no_arg_tool_parameters(),
    strict=False,
)


def should_offer_complete(
    skill_catalog: SkillCatalog,
    active_target_id: Optional[str],
) -> bool:
    """Return whether the LLM ``complete`` tool belongs in this turn's schema.

    Offered when the active target is prose. Withheld while an ordered block is
    active because blocks finish via ``END`` before returning to parent prose.
    """
    if active_target_id is None:
        return False
    skill = skill_catalog.owning_skill_for_target_id(active_target_id)
    if skill is None:
        return False
    if is_ordered_block_target_id(skill.id, active_target_id):
        return False
    return skill_has_prose(skill)


