def _build_activate_schema(
    routable_target_ids: List[str],
) -> Dict[str, Any]:
    """Build the LLM ``activate`` tool schema from allowed entry ids.

    The schema exposes ``target_id`` with an enum of ids the model may activate
    this turn. With nothing active, those ids are skill ids. While a hybrid
    skill is active, the enum can also include a block the skill's prose names
    with ``@block``, or a same-skill block already parked on the stack.

    Args:
        routable_target_ids: Ordered ids from
            :meth:`~rasa.mantle.skills.catalog.SkillCatalog.get_startable_candidate_target_ids`.
    """
    target_id_schema: Dict[str, Any] = {
        "type": "string",
        "description": (
            "A skill id, `{skill_id}__{block_id}` for an ordered block the "
            "active skill's prose names with @block, or a parked same-skill "
            "block id listed in the prompt."
        ),
    }
    if routable_target_ids:
        target_id_schema["enum"] = sorted(routable_target_ids)

    return {
        "type": _TOOL_FUNCTION,
        "function": {
            "name": TOOL_ACTIVATE,
            "description": (
                "Start or switch to a skill by its skill id. Also accepts the "
                "id of an ordered block the active skill's prose names with "
                "@block, or a parked same-skill block listed in the prompt."
            ),
            "parameters": {
                "type": "object",
                "properties": {"target_id": target_id_schema},
                "required": ["target_id"],
            },
        },
    }


def _build_search_knowledge_schema() -> Dict[str, Any]:
    """Build the static ``search_knowledge`` schema (one ``query`` string param).

    Offered whenever a knowledge base is configured. The model calls it to look
    up information it needs to answer the user; results come back as a tool
    message and the model may search again with a refined query before answering.
    """
    return {
        "type": _TOOL_FUNCTION,
        "function": {
            "name": TOOL_SEARCH_KNOWLEDGE,
            "description": (
                "Search the configured knowledge base for information needed to "
                "answer the user's question. Call this for informational questions "
                "before answering; you may call it again with a refined query."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "query": {
                        "type": "string",
                        "description": "What to look up, as a natural-language query.",
                    }
                },
                "required": ["query"],
            },
        },
    }


def _build_cannot_help_schema() -> Dict[str, Any]:
    """Build the static ``cannot_help`` schema (one ``in_domain`` boolean param).

    The model calls this only when neither the active skill nor any available
    routable skill can fulfil the request. An in-domain informational gap gets a
    "not certain" reply, not a decline. ``in_domain`` selects the request type:
    ``true`` when the request is within the agent's domain but not a supported
    task (in-domain out-of-scope), ``false`` when it is unrelated to the agent's
    domain (out-of-domain out-of-scope). Dispatch activates the bundled,
    builder-customizable decline skill, which utters the matching decline and
    ends the turn.
    """
    return {
        "type": _TOOL_FUNCTION,
        "function": {
            "name": TOOL_CANNOT_HELP,
            "description": (
                "Decline only when neither the active skill nor any available "
                "routable skill can fulfil the request. Requests remain supported "
                "when they can be handled from skill instructions, conversation "
                "context, prior tool results, or currently available tools, "
                "including contextual follow-ups, comparisons, revised choices "
                "or corrections, and re-running dependent work. An active skill "
                "does not block a decline when neither that skill nor any "
                "available routable skill can answer or act. If the knowledge "
                "base lacks an answer to an informational "
                "question, say you are not certain instead of declining. Set "
                "in_domain=true for an unsupported request within the agent's "
                "domain and in_domain=false for one outside it."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "in_domain": {
                        "type": "boolean",
                        "description": (
                            "True if the request is within this agent's domain "
                            "but unsupported; False if outside its domain."
                        ),
                    }
                },
                "required": ["in_domain"],
            },
        },
    }


def _build_listen_schema() -> Dict[str, Any]:
    """Build the static ``listen`` schema (no parameters).

    The model calls this to end the turn without a user-facing message.
    Offered on main LLM calls except on a text collect step, a voice collect
    step whose question has not been asked yet, post-search answer calls, and
    pending tool confirmation.
    Mixed with text or other tools, the engine ignores this call, so the
    description tells the model not to precede it with an acknowledgement.
    """
    return {
        "type": _TOOL_FUNCTION,
        "function": {
            "name": TOOL_LISTEN,
            "description": (
                "Wait without sending a message. Call only if you already "
                "asked a question and are still waiting for that answer, "
                "for example when the user started answering but hasn't "
                "finished (e.g. only part of a card number). If the answer "
                "looks cut off (it trails off with 'and' or 'uh', or is too "
                "short for what you asked), do not save it; call this and "
                "wait for the rest. Call it with no text at all, not even an "
                "acknowledgement. Do not call as "
                "a silent reply to the user, and do not call if you still "
                "need to reply or use another tool."
            ),
            "parameters": {"type": "object", "properties": {}, "required": []},
        },
    }


def _build_correct_schema(
    correctable_memory_items: Sequence["CorrectableMemoryItem"],
) -> Optional[Dict[str, Any]]:
    """Build the per-turn ``correct`` schema, or ``None`` when nothing is correctable.

    Like ``activate``, the schema is rebuilt each turn with a dynamic
    ``memory_key`` enum and a description that lists each correctable memory item
    with its declared type, current value, and (where declared) its allowed
    values, so the LLM can target the right earlier decision and supply a
    well-typed value.

    Args:
        correctable_memory_items: The memory items eligible for correction this
            turn, from
            :func:`~rasa.mantle.orchestration.correction.find_correctable_fields`.
    """
    if not correctable_memory_items:
        return None

    memory_item_lines: List[str] = []
    for item in correctable_memory_items:
        detail = item.resolved_description or ""
        allowed = (
            f" allowed values: {', '.join(str(v) for v in item.field.enum_values)};"
            if item.field.enum_values
            else ""
        )
        memory_item_lines.append(
            f"  - {item.memory_key} (type: {item.field.type}, "
            f"current value: {item.current_value!r}):{allowed} {detail}".rstrip()
        )

    description = (
        "Correct a value the user already provided earlier when they revise it "
        "later in the conversation. Use this ONLY to revisit an EARLIER "
        "decision — never to answer the question being asked right now. "
        "The 'value' you pass must match the type listed for the chosen "
        "memory_key below; for a memory item with allowed values, 'value' must "
        "be exactly one of those listed values. "
        "Correctable memory items:\n" + "\n".join(memory_item_lines)
    )

    # TODO:
    #   Today correct() is single-item by design: the replay driver anchors the
    #   rewind at one produced value and clears/re-walks from that single anchor.
    #   Accepting a list means multi-anchor replay — combining clear-sets across
    #   several corrected values, ordering the producer re-invokes, and handling
    #   partial producer rejection — which is a design change rather than a schema
    #   tweak. The user can still correct items across consecutive turns in the
    #   meantime. Tracking as a focused follow-up.

    return {
        "type": _TOOL_FUNCTION,
        "function": {
            "name": TOOL_CORRECT,
            "description": description,
            "parameters": {
                "type": "object",
                "properties": {
                    "memory_key": {
                        "type": "string",
                        "enum": [item.memory_key for item in correctable_memory_items],
                        "description": "The earlier memory item to correct.",
                    },
                    "value": {
                        "description": (
                            "The corrected value for the memory item, in its own "
                            "type (e.g. a string, boolean, or number)."
                        ),
                    },
                },
                "required": ["memory_key", "value"],
            },
        },
    }


def _build_resolve_tool_confirmation_schema(
    tool_name: str,
    confirmation_ask: str | None,
) -> Dict[str, Any]:
    """Build the per-turn ``resolve_tool_confirmation`` schema.

    Offered only while a builder tool is paused on ``requires_confirmation``. The
    LLM interprets the user's reply and sets ``confirmed`` accordingly.

    When supplied, the description embeds the substituted confirmation ask so
    the model can interpret the user's reply in context. Treat it like other
    user-visible copy (it may include memory values); do not log at INFO+.
    """
    context = (
        f"The agent asked the user: {confirmation_ask!r} "
        if confirmation_ask is not None
        else "The agent asked the user to confirm "
    )
    leave_skill = (
        ""
        if tool_name == TOOL_CANCEL
        else (
            " If they want to leave the whole active skill, call cancel "
            "instead of resolving this tool as a no."
        )
    )
    return {
        "type": _TOOL_FUNCTION,
        "function": {
            "name": TOOL_RESOLVE_TOOL_CONFIRMATION,
            "description": (
                "Resolve a pending tool confirmation. "
                f"{context}before running '{tool_name}'. Interpret "
                "the user's latest reply: set confirmed=true if they agreed to "
                "proceed with this tool, or confirmed=false if they explicitly "
                "declined this tool."
                f"{leave_skill} If they asked a question or "
                "switched to another supported task, do not call this tool yet; "
                "keep the confirmation pending while handling their request."
            ),
            "parameters": {
                "type": "object",
                "properties": {
                    "confirmed": {
                        "type": "boolean",
                        "description": (
                            "True to run the pending tool; False to cancel it."
                        ),
                    }
                },
                "required": ["confirmed"],
            },
        },
    }


def _build_field_property_schema(
    field_name: str,
    field: Optional[MemoryField],
    description: Optional[str],
) -> Dict[str, Any]:
    """Build one ``set_fields`` object-property schema for a single field.

    Shared building block for the batch collect tool: value type and
    categorical ``enum`` are derived from the memory entry so the LLM sends a
    natively typed, enum-constrained value for each property it fills.
    """
    enum_values = (
        field.enum_values
        if field is not None and field.type == MEMORY_FIELD_TYPE_CATEGORICAL
        else None
    )
    prop: Dict[str, Any] = {
        "type": _json_type_for_memory_entry(field),
        "description": description or f"The value for '{field_name}'.",
    }
    if enum_values:
        prop["enum"] = list(enum_values)
        allowed = ", ".join(str(v) for v in enum_values)
        prop["description"] = f"{prop['description']} Allowed values: {allowed}."
    return prop


def _build_set_fields_schema(
    field_names: List[str],
    memory_fields: Mapping[str, MemoryField],
    descriptions: Mapping[str, Optional[str]],
) -> Dict[str, Any]:
    """Build the single batch ``set_fields`` tool schema.

    One typed, optional object property per entry in *field_names* — every
    settable memory entry exposed for the active skill this turn (``llm_settable``
    fields plus collect targets). A single batch tool keeps the tool
    list short regardless of how many settable fields a skill declares. The
    model includes only the fields it can confidently fill in one call and
    omits the rest — every property is optional so a partial fill is always
    valid.

    Args:
        field_names: Settable memory entry names to expose this turn.
        memory_fields: The active skill's ``{entry_name: MemoryField}`` map,
            for value-type and categorical-enum inference.
        descriptions: Field name → description already resolved for this turn.
            A missing description uses a generic placeholder.
    """
    properties: Dict[str, Any] = {
        field_name: _build_field_property_schema(
            field_name,
            memory_fields.get(field_name),
            descriptions.get(field_name),
        )
        for field_name in field_names
    }
    return {
        "type": _TOOL_FUNCTION,
        "function": {
            "name": TOOL_SET_FIELDS,
            "description": (
                "Record any of the listed memory fields the user has already "
                "provided, in one call. This is not limited to the value being "
                "asked for at the current step: include every listed field the "
                "user has stated anywhere in the conversation so it is not asked "
                "for again. Include only the fields you can confidently fill "
                "from the conversation so far; omit the rest."
            ),
            "parameters": {
                "type": "object",
                "properties": properties,
                "required": [],
            },
        },
    }


# ---------------------------------------------------------------------------
# Custom tool schema helpers
# ---------------------------------------------------------------------------

_INJECTED_TOOL_PARAMS = frozenset({"context", "tracker_handle"})


def agent_tool_schema_from_custom_tool(name: str, func: Callable) -> AgentToolSchema:
    """Build the canonical schema for a user-defined ``@tool`` function."""
    sig = inspect.signature(func)
    try:
        type_hints = typing.get_type_hints(func)
    except Exception:
        type_hints = {}
    properties: Dict[str, Any] = {}
    required: List[str] = []
    for param_name, param in sig.parameters.items():
        if param_name in _INJECTED_TOOL_PARAMS:
            continue
        annotation = type_hints.get(param_name, param.annotation)
        properties[param_name] = _annotation_to_json_schema(annotation)
        if param.default is inspect.Parameter.empty:
            required.append(param_name)

    parameters: Dict[str, Any] = {
        "type": "object",
        "properties": properties,
        "required": required,
        "additionalProperties": False,
    }
    AgentToolSchema._validate_and_fix_parameters(parameters)
    description = getattr(func, "_tool_description", None) or name
    return AgentToolSchema(
        name=name,
        description=description,
        parameters=parameters,
        strict=False,
    )


def resolve_builder_tool_schema(
    *,
    skill_id: str,
    tool_name: str,
    tool_func: Optional[Callable[..., Any]],
    mcp_runtime: Optional["MCPRuntime"] = None,
) -> Optional[AgentToolSchema]:
    """Return the schema offered for a local or imported MCP tool."""
    if mcp_runtime is not None:
        mcp_schema = mcp_runtime.mcp_tool_schemas.get(skill_id, {}).get(tool_name)
        if isinstance(mcp_schema, AgentToolSchema):
            return mcp_schema
    if tool_func is None:
        return None
    return agent_tool_schema_from_custom_tool(tool_name, tool_func)


def _to_litellm_tool(schema: AgentToolSchema) -> Dict[str, Any]:
    """Emit the LiteLLM/OpenAI JSON the completion API expects."""
    return schema.to_litellm_json_format()


def _builtin_agent_tool_schema(schema: Mapping[str, Any]) -> AgentToolSchema:
    """Lift a hard-coded OpenAI-shaped built-in schema into the canonical type."""
    return AgentToolSchema.from_litellm_json_format(dict(schema))


def canonicalize_tool_schemas(
    schemas: Sequence[AgentToolSchema | Mapping[str, Any]],
) -> List[AgentToolSchema]:
    """Normalize mixed built-in dicts / ``AgentToolSchema`` to the canonical type."""
    return [
        schema
        if isinstance(schema, AgentToolSchema)
        else _builtin_agent_tool_schema(schema)
        for schema in schemas
    ]


def emit_litellm_tools(
    schemas: Sequence[AgentToolSchema | Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    """Convert canonical schemas (or OpenAI dicts) to LiteLLM/OpenAI JSON."""
    return [_to_litellm_tool(schema) for schema in canonicalize_tool_schemas(schemas)]


def _unwrap_optional(annotation: Any) -> Any:
    """Unwrap ``Optional[T]`` / ``T | None`` to ``T``.

    Returns the annotation unchanged when it is not an optional union.
    """
    origin = getattr(annotation, "__origin__", None)
    if origin is typing.Union:
        args = [a for a in annotation.__args__ if a is not type(None)]
        if len(args) == 1:
            return args[0]
    return annotation


def _annotation_to_json_schema(annotation: Any) -> Dict[str, Any]:
    """Map a Python type annotation to an OpenAI-compatible JSON schema dict.

    Handles plain types (``int``, ``str``, …), generic list types
    (``list[str]``, ``List[str]``, …), and optional wrappers
    (``Optional[T]``, ``T | None``).  Unknown annotations default to
    ``{"type": "string"}``.

    Examples::

        _annotation_to_json_schema(int)            == {"type": "integer"}
        _annotation_to_json_schema(bool | None)    == {"type": "boolean"}
        _annotation_to_json_schema(list[str])      == {
            "type": "array", "items": {"type": "string"}}
        _annotation_to_json_schema(list)           == {"type": "array"}
    """
    annotation = _unwrap_optional(annotation)
    origin = getattr(annotation, "__origin__", None)
    if origin is list:
        args = getattr(annotation, "__args__", None)
        if args:
            item_type = _PY_TYPE_TO_JSON.get(args[0], "string")
            return {"type": "array", "items": {"type": item_type}}
        return {"type": "array"}
    if annotation is list:
        return {"type": "array"}
    json_type = _PY_TYPE_TO_JSON.get(annotation, "string")
    return {"type": json_type}


def build_custom_tool_schemas(
    declared_names: List[str],
    flow_tool_funcs: Mapping[str, Callable],
    mcp_schemas: Optional[Mapping[str, AgentToolSchema]] = None,
) -> List[Dict[str, Any]]:
    """Build OpenAI schemas for an activation target's builder-defined tools.

    Only tools whose names appear in *declared_names* **and** have a matching
    callable in *flow_tool_funcs* or a listed MCP schema in *mcp_schemas* are
    included. The parameter named
    ``context`` (the injected :class:`~rasa.mantle.tools.decorator.ToolContext`)
    is excluded from the schema — it is runtime-injected and not LLM-facing.

    Args:
        declared_names: Tool names available to the active target.
        flow_tool_funcs: Mapping of ``{tool_name: func}`` for the active target.
            The parameter retains its compatibility name until the remaining
            flow API is removed.
        mcp_schemas: Listed MCP schemas keyed by bare tool name.

    Returns:
        A list of OpenAI-format tool schema dicts for the matching tools.
    """
    remote_schemas = mcp_schemas or {}
    schemas: List[AgentToolSchema] = []
    for name in declared_names:
        remote = remote_schemas.get(name)
        if remote is not None:
            schemas.append(remote)
            continue
        func = flow_tool_funcs.get(name)
        if func is None:
            continue
        schemas.append(agent_tool_schema_from_custom_tool(name, func))
    return emit_litellm_tools(schemas)


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


# ---------------------------------------------------------------------------
# Tool schemas (SkillCatalog-aware with GatedTool gating)
# ---------------------------------------------------------------------------


def tools_for_skill(
    skill_id: str,
    bootstrap: "ModelBootstrap",
    mcp_runtime: Optional["MCPRuntime"] = None,
) -> list[AgentToolSchema]:
    """Return the ungated local + MCP inventory for *skill_id*.

    Memory validation tools and response ``buttons.source`` tools are omitted (the
    engine invokes them; the LLM never calls them). Framework tools and
    ``tool_constraints`` gates are not applied.
    """
    schemas: list[AgentToolSchema] = []
    hidden_tool_names = button_source_names_for_skill(
        bootstrap.skill_catalog,
        bootstrap.response_registry,
        skill_id,
    )
    for name, func in bootstrap.tool_funcs.get(skill_id, {}).items():
        if is_memory_validation_tool(name) or name in hidden_tool_names:
            continue
        schemas.append(agent_tool_schema_from_custom_tool(name, func))
    if mcp_runtime is not None:
        schemas.extend(
            schema
            for name, schema in mcp_runtime.mcp_tool_schemas.get(skill_id, {}).items()
            if name not in hidden_tool_names
        )
    return schemas


def all_available_tools(
    bootstrap: "ModelBootstrap",
    mcp_runtime: Optional["MCPRuntime"] = None,
) -> list[AgentToolSchema]:
    """Return ungated local + MCP schemas across every skill."""
    skill_ids = set(bootstrap.tool_funcs) | set(bootstrap.mcp_tool_allowlist)
    if mcp_runtime is not None:
        skill_ids |= set(mcp_runtime.mcp_tool_schemas)
    schemas: list[AgentToolSchema] = []
    for skill_id in sorted(skill_ids):
        schemas.extend(tools_for_skill(skill_id, bootstrap, mcp_runtime))
    return schemas


def build_llm_tools_for_turn(
    *,
    bootstrap: "ModelBootstrap",
    memory_values: Mapping[str, Any],
    mcp_runtime: Optional["MCPRuntime"] = None,
    active_target_id: Optional[str] = None,
    settable_fields: Optional[List[str]] = None,
    settable_descriptions: Optional[Dict[str, Optional[str]]] = None,
    correctable_memory_items: Optional[Sequence["CorrectableMemoryItem"]] = None,
    knowledge_available: bool = False,
    knowledge_searched: bool = False,
    pending_tool_confirmation: Optional[PendingToolConfirmation] = None,
    listen_available: bool,
    allowed_target_ids: Optional[Sequence[str]] = None,
    paused_block_ids: Sequence[str] = (),
) -> List[AgentToolSchema]:
    """Build the gated tool schema list for one LLM completion call.

    Resolves the skill catalog, local tool registry, MCP listed schemas, and
    project memory from *bootstrap* / *mcp_runtime*, then applies routing,
    ``tool_constraints`` / ordered-block ``requires`` gates, and per-turn
    framework tools (``activate``, ``set_fields``, ``correct``, etc.).

    Settable memory entries (*settable_fields*) are exposed as a single batch
    ``set_fields`` tool (see :func:`_build_set_fields_schema`), so the tool list
    stays short regardless of how many settable fields a skill declares. Value
    types and categorical enums are inferred from the active skill's
    :class:`~rasa.mantle.memory.schema.SkillMemoryContract` so the LLM sends
    natively typed values rather than always a string. Descriptions are sourced
    from the collect step (via *settable_descriptions*) with a fallback to the
    memory entry's description.

    Args:
        bootstrap: Loaded model bundle (skill catalog, tool funcs, project memory).
            Project fields from the bundle are used when typing ``set_fields``
            properties; they are never LLM-settable, so they do not add names
            to the schema.
        memory_values: Current memory values used for routing and gating
            expressions (e.g. ``{"slot": value}``, accessed as ``session.slot``).
        mcp_runtime: Processor-owned MCP runtime; when set, listed MCP schemas are
            merged into the active skill's custom tools.
        active_target_id: Flow ID of the currently active stack frame, if any.
            Used to resolve the owning skill via
            :meth:`~rasa.mantle.skills.catalog.SkillCatalog.owning_skill_for_target_id`.
            When provided, gated custom tool schemas are appended for the
            skill's declared tools.
        settable_fields: Memory entry names to expose on the batch ``set_fields``
            tool this turn — ``llm_settable`` fields plus collect targets
            for the active skill (see ``SkillExecutor.settable_fields_for_turn``).
        settable_descriptions: Optional mapping of field name → description
            from the owning :class:`~rasa.mantle.skills.steps.CollectStep` or
            :attr:`~rasa.mantle.memory.field.MemoryField.description`.
        correctable_memory_items: Memory items eligible for cross-phase
            correction this turn (from
            :func:`~rasa.mantle.orchestration.correction.find_correctable_fields`).
            When non-empty, a per-turn ``correct`` tool is added with a dynamic
            ``memory_key`` enum; when empty/omitted, no correction tool is offered.
        knowledge_available: Whether a knowledge base is configured (a packaged
            ``references/`` index is present). When ``True`` and the builder
            has not turned ``search_knowledge`` off in
            ``orchestrator.tool_constraints``, the static ``search_knowledge``
            tool is offered so the model can retrieve on demand — in routing
            mode and while a skill is active alike — and ``cannot_help`` is
            withheld until a search has run this turn (so the model cannot
            decline before the context is possibly complete). When ``False``,
            or when ``search_knowledge`` is turned off, ``cannot_help`` is
            offered immediately and the index is not searched.
        knowledge_searched: Whether ``search_knowledge`` has already been called
            this turn. When ``True``, only ``activate``,
            ``search_knowledge`` and ``cannot_help`` are offered; the active
            skill's lifecycle, collect, builder, and ``listen``
            tools are dropped so the grounded answer does not re-drive the
            skill or end silently before presenting the retrieved
            information.
        pending_tool_confirmation: Optional pending confirmation payload when a
            builder tool is paused on ``requires_confirmation``. When set, a
            ``resolve_tool_confirmation`` tool is offered so the LLM can
            interpret the user's reply.
        listen_available: Whether this LLM call may wait silently. The
            orchestrator computes this for the turn (false on a text collect
            step, on a voice collect step whose question has not been asked
            yet, post-search, and pending confirmation). Required so a caller
            cannot omit the engine
            decision. Post-search and pending confirmation also withhold
            ``listen`` here even if the flag is ``True``.
        allowed_target_ids: When set, the ``activate`` enum is restricted to
            this FAISS-filtered legal list. ``None`` keeps the full startable
            candidate set.
        paused_block_ids: Compiled ids of same-skill blocks parked under the
            active frame. Added to the ``activate`` enum so the model can
            resume a block the prompt lists. Unparked ``call:`` and ``link:``
            targets are not included.

    Returns:
        Canonical :class:`AgentToolSchema` objects. Convert to LiteLLM/OpenAI
        JSON with :func:`emit_litellm_tools` immediately before the provider call.
    """
    # Local import: this module defines the tool-name constants that
    # builtin_tool_constraints imports, so a module-level import cycles.
    from rasa.mantle.config.builtin_tool_constraints import knowledge_search_offered

    constraints = bootstrap.agent.orchestrator.tool_constraints
    knowledge_available = knowledge_search_offered(constraints, knowledge_available)

    skill_catalog = bootstrap.skill_catalog
    skill_tool_funcs = bootstrap.tool_funcs
    mcp_tool_schemas = mcp_runtime.mcp_tool_schemas if mcp_runtime is not None else None
    project_memory_fields = bootstrap.project_memory.fields

    schemas: List[AgentToolSchema | Dict[str, Any]] = []

    startable_candidate_target_ids = apply_allowed_target_ids(
        skill_catalog.get_startable_candidate_target_ids(
            dict(memory_values),
            active_target_id=active_target_id,
            paused_block_ids=paused_block_ids,
        ),
        allowed_target_ids,
    )
    if startable_candidate_target_ids:
        schemas.append(_build_activate_schema(startable_candidate_target_ids))

    # search_knowledge is available alongside activate in both routing mode
    # and while a skill is active, so the model can retrieve at any point in the
    # turn.
    if knowledge_available:
        schemas.append(_build_search_knowledge_schema())

    # cannot_help is a routing-level decline available in both routing mode and
    # while a skill is active. It is gated so the model cannot decline before the
    # context is possibly complete: offered only once search_knowledge has run
    # this turn, or immediately when no knowledge base is configured. Appended
    # before the post-search early return below so it survives the trim that
    # keeps activate, search_knowledge, cannot_help, and resolve when pending
    # (the model may still need to decline once a search turns up nothing
    # relevant).
    if knowledge_searched or not knowledge_available:
        schemas.append(_build_cannot_help_schema())

    # resolve_tool_confirmation must survive the post-search trim the same way
    # cannot_help does: it is the only way to unblock requires_confirmation after a
    # clarifying search during a confirmation pause.
    if pending_tool_confirmation is not None:
        schemas.append(
            _build_resolve_tool_confirmation_schema(
                pending_tool_confirmation.tool_name,
                pending_tool_confirmation.confirmation_ask,
            )
        )

    # Collect is gated only via listen_available (no collect handle here).
    # Post-search and pending confirmation fail closed even if that flag is
    # still True — those calls must answer, not wait silently.
    if (
        listen_available
        and not knowledge_searched
        and pending_tool_confirmation is None
    ):
        schemas.append(_build_listen_schema())

    # Once search_knowledge has run this turn, the only tools kept are
    # activate + search_knowledge (re-query) plus cannot_help and, when a
    # confirmation is pending, resolve_tool_confirmation. The active skill's
    # lifecycle / collect / builder / listen tools are dropped so the
    # grounded answer does not re-drive the skill or end silently;
    # they return on a later turn once no search has run, or after an activate.
    # Mirrors the active-skill prompt trim.
    if knowledge_searched:
        return _drop_disabled_builtin_tools(
            canonicalize_tool_schemas(schemas), constraints
        )

    # cancel acts on the active skill. complete is for skills that
    # have prose; block-only skills complete via END, so the tool is omitted.
    if active_target_id is not None:
        if should_offer_complete(skill_catalog, active_target_id):
            schemas.append(_COMPLETE_SCHEMA)
        schemas.append(_CANCEL_SCHEMA)

    # Per-turn correction tool: present only when ≥1 earlier value is correctable.
    correct_schema = _build_correct_schema(correctable_memory_items or [])
    if correct_schema is not None:
        schemas.append(correct_schema)

    active_skill = (
        skill_catalog.owning_skill_for_target_id(active_target_id)
        if active_target_id
        else None
    )
    _append_set_fields_schema(
        schemas,
        active_skill=active_skill,
        settable_fields=settable_fields,
        settable_descriptions=settable_descriptions,
        project_memory_fields=project_memory_fields,
    )
    _append_custom_tool_schemas(
        schemas,
        skill_catalog=skill_catalog,
        active_skill=active_skill,
        active_target_id=active_target_id,
        skill_tool_funcs=skill_tool_funcs,
        mcp_tool_schemas=mcp_tool_schemas,
        response_registry=bootstrap.response_registry,
        memory_values=memory_values,
    )
    return _drop_disabled_builtin_tools(canonicalize_tool_schemas(schemas), constraints)


def _drop_disabled_builtin_tools(
    schemas: List[AgentToolSchema],
    constraints: Mapping[str, BuiltinToolConstraint],
) -> List[AgentToolSchema]:
    """Remove built-in tools the builder turned off.

    Offer rules run first. ``enabled: true`` does not add a tool those rules
    withheld.
    """
    from rasa.mantle.config.builtin_tool_constraints import builtin_tool_enabled

    return [
        schema for schema in schemas if builtin_tool_enabled(constraints, schema.name)
    ]


def _gated_tool_is_active(tool: GatedTool, memory_values: Mapping[str, Any]) -> bool:
    """Return ``True`` when *tool* should be included in the LLM tool list.

    A tool without a ``requires`` expression is always active.  A tool with
    ``requires`` is active only when the expression evaluates to a truthy value.

    Evaluation errors are treated as *inactive* (fail closed) so that a broken
    gate expression hides the tool rather than offering it to the LLM and then
    blocking it at dispatch — which would waste turns in a stuck loop.  This
    mirrors the behaviour of :meth:`SkillExecutor._is_tool_gate_open`.
    """
    if tool.requires is None:
        return True
    try:
        return bool(evaluate_expression(tool.requires, memory_values))
    except Exception:
        return False


def visible_custom_tool_names(
    skill_catalog: SkillCatalog,
    skill_id: str,
    active_target_id: str,
    skill_funcs: Mapping[str, Callable],
    memory_values: Mapping[str, Any],
    mcp_tool_names: Iterable[str] = (),
    hidden_tool_names: AbstractSet[str] = frozenset(),
) -> list[str]:
    """Return builder-defined tool names visible to the LLM this turn.

    Visibility rules:

    * **Skill-local** ``@tool`` functions loaded into *skill_funcs* are exposed
      unless the name appears in ``tool_constraints`` (including ordered-block
      ``tools`` lists) and the gate is inactive.
    * **Shared** agent-root tools are exposed only when listed in
      ``import_tools`` (the loader already scopes *skill_funcs*); gate
      expressions from ``tool_constraints`` still apply.

    Ordered-block ``tools`` lists use the same gating semantics as
    ``tool_constraints`` for skill-local tools.

    This is the single source of truth for custom-tool schema visibility; the
    runtime dispatcher mirrors it (gating applies only when a matching
    :class:`~rasa.mantle.skills.conditions.GatedTool` exists).
    """
    gates = skill_catalog.resolve_tool_gates(skill_id, active_target_id)
    gates_by_name = {gate.name: gate for gate in gates}
    from rasa.mantle.tools.mcp_import_spec import get_bare_tool_name

    tool_names = {
        get_bare_tool_name(reference)
        for reference in skill_catalog.import_tool_names(skill_id)
    }
    constraint_names = skill_catalog.tool_constraint_names(skill_id)

    visible: list[str] = []
    candidate_names = list(skill_funcs)
    for name in mcp_tool_names:
        if name not in candidate_names:
            candidate_names.append(name)
    for name in candidate_names:
        # Memory validation tools (``run_after_setting_<entry>``) are engine-invoked
        # after a settable write; the LLM never calls them, so they are never
        # exposed in the tool list.
        if is_memory_validation_tool(name) or name in hidden_tool_names:
            continue
        if name in tool_names:
            gate = gates_by_name.get(name)
            if gate is None or _gated_tool_is_active(gate, memory_values):
                visible.append(name)
            continue

        if name in constraint_names:
            gate = gates_by_name.get(name)
            if gate is not None and _gated_tool_is_active(gate, memory_values):
                visible.append(name)
            continue

        visible.append(name)

    return visible


def _append_set_fields_schema(
    schemas: List[AgentToolSchema | Dict[str, Any]],
    *,
    active_skill: Optional[Skill],
    settable_fields: Optional[List[str]],
    settable_descriptions: Optional[Dict[str, Optional[str]]],
    project_memory_fields: Optional[Mapping[str, MemoryField]],
) -> None:
    """Append the batch ``set_fields`` schema when settable fields are present."""
    if not settable_fields:
        return
    active_skill_fields = (
        active_skill.memory.definition.all_fields() if active_skill else {}
    )
    # Skill-local fields win on a name collision with a project field.
    memory_fields = {**(project_memory_fields or {}), **active_skill_fields}
    schemas.append(
        _build_set_fields_schema(
            settable_fields,
            memory_fields,
            settable_descriptions or {},
        )
    )


def build_set_fields_tools_for_turn(
    *,
    bootstrap: "ModelBootstrap",
    settable_fields: Optional[List[str]] = None,
    settable_descriptions: Optional[Dict[str, Optional[str]]] = None,
    active_target_id: Optional[str] = None,
) -> List[AgentToolSchema]:
    """Build the ``set_fields`` schema for a silent memory-extraction call.

    Returns an empty list when nothing is settable. The schema matches the
    ``set_fields`` tool from :func:`build_llm_tools_for_turn`; other framework
    and builder tools are omitted.

    Args:
        bootstrap: Loaded model bundle used for skill ownership and project
            memory field types.
        settable_fields: Memory entry names to expose on ``set_fields``.
        settable_descriptions: Optional field name → collect-step description.
        active_target_id: Flow ID of the active stack frame, used to resolve
            the owning skill's memory contract.

    Returns:
        Canonical ``set_fields`` schemas, or an empty list.
    """
    schemas: List[AgentToolSchema | Dict[str, Any]] = []
    active_skill = (
        bootstrap.skill_catalog.owning_skill_for_target_id(active_target_id)
        if active_target_id
        else None
    )
    _append_set_fields_schema(
        schemas,
        active_skill=active_skill,
        settable_fields=settable_fields,
        settable_descriptions=settable_descriptions,
        project_memory_fields=bootstrap.project_memory.fields,
    )
    return canonicalize_tool_schemas(schemas)


def _append_custom_tool_schemas(
    schemas: List[AgentToolSchema | Dict[str, Any]],
    *,
    skill_catalog: SkillCatalog,
    active_skill: Optional[Skill],
    active_target_id: Optional[str],
    skill_tool_funcs: Optional[Mapping[str, Mapping[str, Callable]]],
    mcp_tool_schemas: Optional[Mapping[str, Mapping[str, AgentToolSchema]]],
    response_registry: "ResponseRegistry",
    memory_values: Mapping[str, Any],
) -> None:
    """Append gated custom tool schemas for the active skill, if any."""
    if active_target_id is None:
        return
    skill_id = active_skill.id if active_skill else active_target_id
    skill_funcs = (skill_tool_funcs or {}).get(skill_id, {})
    skill_mcp = (mcp_tool_schemas or {}).get(skill_id, {})
    if not skill_funcs and not skill_mcp:
        return
    active_tool_names = visible_custom_tool_names(
        skill_catalog,
        skill_id,
        active_target_id,
        skill_funcs,
        memory_values,
        mcp_tool_names=skill_mcp,
        hidden_tool_names=button_source_names_for_skill(
            skill_catalog,
            response_registry,
            skill_id,
        ),
    )
    if active_tool_names:
        schemas.extend(
            build_custom_tool_schemas(
                active_tool_names, skill_funcs, mcp_schemas=skill_mcp
            )
        )


def tool_gate_statuses(
    skill_catalog: SkillCatalog,
    skill_id: str,
    active_target_id: Optional[str],
    memory_values: Mapping[str, Any],
) -> dict[str, bool]:
    """Return the gate result per tool declared for the skill/flow context.

    Uses the same gate resolution and fail-closed evaluation as the LLM
    schema builder, so ``False`` here means exactly "not offered to the LLM
    right now". Single source of truth for observability consumers (the
    Inspector's ``tools`` panel and the call record's ``gated_tool_names``)
    — never used for dispatch decisions.
    """
    gates = skill_catalog.resolve_tool_gates(skill_id, active_target_id or "")
    return {gate.name: _gated_tool_is_active(gate, memory_values) for gate in gates}


def inactive_gated_tool_names(
    skill_catalog: SkillCatalog,
    skill_id: str,
    active_target_id: Optional[str],
    memory_values: Mapping[str, Any],
) -> list[str]:
    """Return declared tool names whose gate is currently inactive.

    The complement of what :func:`build_llm_tools_for_turn` offers for the same
    context: tools the author declared (skill-level or on the active flow)
    that are withheld from the LLM because their ``requires`` expression
    evaluates falsy (or fails — fail closed, mirroring the schema builder).
    Used for observability (call-record metadata), never for dispatch
    decisions.
    """
    statuses = tool_gate_statuses(
        skill_catalog, skill_id, active_target_id, memory_values
    )
    return [name for name, active in statuses.items() if not active]
